"""Source-grounded additional questions. Independent review required."""
from author_common import *

def mc(doc,page,prompt,correct,distractors,why,scenario=None):
    add(doc,page,'scenario' if scenario else 'single_choice',prompt,'a',why,[correct]+distractors,context=scenario)
    q=qs[-1];q['id']=f'{doc}-x{sum(x["topic"]==doc for x in qs):02}';q['author_id']='question-engineer-b'

