mc(d,8,'Theo decision framework, yêu cầu giữ dữ liệu tại Việt Nam dẫn nhóm tới lựa chọn nào?','Viettel/VNG/FPT',['Bất kỳ region quốc tế nào có GPU rẻ nhất','Chỉ Azure vì có OpenAI API','Chỉ GCP vì có TPU'],'Nhánh VN data residency chỉ tới Viettel/VNG/FPT; quyết định cần xét compliance ngoài chi phí.')
mc(d,9,'Đánh đổi vận hành nào cần tính khi chọn specialized GPU cloud?','Ít managed services và đội phải tự quản nhiều hơn',['Không thể chạy workload GPU','Bắt buộc dùng đầy đủ dịch vụ managed như hyperscaler','Luôn có nhiều availability zone hơn hyperscaler'],'Slide nêu specialized cloud rẻ hơn nhưng ít managed services, cần tự quản và có ít availability zones.')
mc(d,12,'Landing Zone dùng SCPs để thực hiện mục đích nào?','Áp đặt security baseline bằng guardrails',['Lưu checkpoint model thay S3','Chia một GPU thành nhiều instance','Thay toàn bộ logging tập trung'],'SCPs được liệt kê ở mục Guardrails để enforce security baseline.')
mc(d,15,'Một training job chấp nhận bị gián đoạn nên cân nhắc chiến lược mua compute nào?','Spot/Preemptible',['Reserved dài hạn chỉ vì job có thể dừng','Luôn on-demand dù có thể retry','Mua compute theo token thay GPU cho mọi training'],'Slide khuyến nghị Spot cho training interruptible, Reserved cho serving ổn định.')
mc(d,17,'Nhiều model nhỏ cần inference song song với tài nguyên được cô lập. Kỹ thuật nào phù hợp mô tả trong slide?','MIG để chia GPU thành các instance',['Overcommit GPU không giới hạn','Tăng context window của từng model','Chuyển mọi orchestrator sang GPU'],'MIG tạo các instance cô lập và tối đa utilization khi phục vụ nhiều model nhỏ.')
mc(d,19,'Trong môi trường Terraform có nhiều người cùng làm, cặp thành phần nào được nêu để quản lý state?','S3 backend và DynamoDB lock',['Redis cache và embedding cache','Public subnet và SSH key','Docker layer và pip cache'],'Infrastructure Setup liệt kê S3 backend + DynamoDB lock cho team environment.')
mc(d,19,'Để tái sử dụng hạ tầng và tách dev/staging/prod, cách kết hợp nào đúng theo slide?','Modules để reuse, workspaces để isolate',['Workspaces để nén model, modules để ghi logs','Một workspace cho tất cả để tránh isolation','Copy thủ công từng VM rồi sửa production'],'Tip Terraform nêu trực tiếp hai vai trò modules và workspaces.')
mc(d,22,'Vì sao đặt cache pip layer trước COPY source trong Docker build?','Giữ layer dependency có thể tái sử dụng khi mã nguồn đổi',['Buộc tải lại toàn bộ dataset mỗi lần build','Thay thế GPU Operator bằng pip','Cho phép overcommit GPU'],'Phần Docker optimization yêu cầu cache pip layer riêng trước COPY source; điều này tách dependency khỏi thay đổi source.')
mc(d,22,'Một pod yêu cầu một NVIDIA GPU. Cấu hình tài nguyên nào khớp best practice?','nvidia.com/gpu requests = limits = 1',['requests = 1 nhưng limits = 0','Không khai báo GPU vì CPU limit tự cấp GPU','Đặt requests lớn hơn limits để chia sẻ tự động'],'Slide nêu GPU requests phải bằng limits và tránh overcommit.')
mc(d,22,'Namespace ml-serving được tách riêng chủ yếu phục vụ điều gì?','RBAC riêng và cô lập production',['Thay thế hoàn toàn model evaluation','Lưu mọi experiment không giới hạn','Tự động loại bỏ mọi chi phí GPU'],'Ba namespace có mục tiêu riêng; ml-serving dành cho separate RBAC và production isolation.')
mc(d,24,'VPC Endpoints/PrivateLink mang lại lợi ích nào được slide nhấn mạnh?','Tránh traffic qua internet và giảm egress cost',['Tăng số token model xử lý','Tự chuyển inference thành training','Thay mọi service mesh bằng public URL'],'Networking slide liên hệ PrivateLink với bảo mật và tiết kiệm egress cost.')
mc(d,25,'Dữ liệu nào phù hợp với Redis/GPU Memory ở tầng hot?','Active KV cache, embedding cache và session state',['Checkpoint rất cũ để tuân thủ lưu trữ','Toàn bộ archive ít được truy cập','Bản sao cold storage của mọi model'],'Hot storage nhắm dữ liệu hoạt động cần độ trễ sub-ms.')
mc(d,28,'Supervisor chỉ điều phối các specialist; không trực tiếp chạy LLM cục bộ. Bố trí compute nào khớp slide?','Supervisor trên CPU, specialist chạy LLM dùng GPU',['Mọi supervisor bắt buộc có H200','Mọi tool call phải dùng GPU riêng','Chuyển message queue sang GPU thay CPU'],'Compute Pattern nêu orchestrator không cần GPU; supervisor CPU dispatch specialist GPU.')
mc(d,28,'Hàng đợi cần throughput cao, durability và khả năng replay cho hệ agent lớn. Lựa chọn nào khớp bảng?','Kafka',['In-process LRU dict','S3 Glacier','Embedding cache'],'Bảng queue gắn Kafka với high throughput, durability và replay.')
mc(d,28,'Đội muốn giảm việc embedding lại cùng truy vấn. Tầng cache nào nhắm đúng mục tiêu?','L3 embedding cache',['L1 chỉ lưu binary model','L2 chỉ ghi audit trail','Cold archive chỉ chứa checkpoint'],'L3 được mô tả tránh re-embed cùng query; L1 là in-process LRU và L2 Redis shared TTL.')
mc(d,31,'RadixAttention khai thác sự giống nhau nào giữa các request?','Prefix chung để tái sử dụng KV cache',['Cùng tên người dùng dù nội dung khác hoàn toàn','Cùng kích thước file Docker','Cùng giá thuê GPU'],'SGLang tái sử dụng KV cache giữa các request có chung prefix, giúp multi-turn.')
mc(d,31,'Nếu gần như mọi request dưới 4K token, cấu hình nào được slide khuyến nghị?','Tune max_model_len theo usage thực tế',['Luôn đặt 128K bất kể workload','Tắt continuous batching cho mọi engine','Đặt GPU memory utilization 95% để bảo đảm không OOM'],'Deploy tips yêu cầu tune max_model_len theo actual usage, không đặt 128K khi 99% request dưới 4K.')

