mc(d,10,'Giữ Bronze nguyên bản giúp xử lý lỗi logic Silver được phát hiện sau hai tháng như thế nào?','Xây lại Silver từ lịch sử nguồn đã giữ',['Chỉ sửa trọng số model để che lỗi','Xin Postgres hiện tại tự tái tạo mọi lịch sử đã mất','Xóa Bronze để tránh dữ liệu cũ'],'Slide nêu có thể xóa Silver và chạy lại từ Bronze; nguồn hiện tại có thể không giữ lịch sử hai tháng.')
mc(d,11,'Một ticket có ba thay đổi trong Bronze. Silver đúng cam kết nên thể hiện thế nào?','Một hàng đại diện thực thể ticket',['Ba hàng tương đương ba ticket mới','Một hàng cho mỗi lần retry','Loại ticket vì có nhiều trạng thái'],'Silver cam kết một hàng = một thực thể, khác Bronze ghi các lần thay đổi.')
mc(d,12,'Vì sao khóa không NULL, không trùng quan trọng với Silver chạy lại nhiều lần?','Cho phép MERGE cập nhật cùng thực thể mà không nhân đôi',['Tự loại mọi lỗi ngữ nghĩa trong nhãn','Thay thế hoàn toàn việc ép kiểu','Biến mọi UPDATE thành bản ghi training độc lập'],'Khóa đáng tin cậy giúp MERGE/upsert; thiếu khóa và chỉ INSERT sẽ nhân đôi khi retry.')
mc(d,14,'Rủi ro vận hành nào cần theo dõi khi dùng Debezium với replication slot?','Slot không được đọc có thể làm đầy đĩa DB nguồn',['Slot tự xóa mọi lịch sử Kafka mỗi phút','WAL chỉ chứa SELECT nên bỏ mọi UPDATE','CDC bắt buộc truy vấn full table sau mỗi message'],'Nguồn mô tả Debezium đọc WAL như replica, đổi lại phải trông replication slot để tránh đầy đĩa.')
mc(d,15,'Nguồn SaaS đa dạng, ngân sách hẹp và muốn connector mã nguồn mở. Công cụ nào khớp bảng?','Airbyte',['Fivetran vì luôn miễn phí theo số dòng','Tự viết mọi connector mà không bảo trì','Chỉ Debezium dù nguồn không có transaction log'],'Bảng mô tả Airbyte mã nguồn mở, nhiều connector, phù hợp nhiều nguồn SaaS và ngân sách hẹp; chất lượng connector không đều là đánh đổi.')
mc(d,16,'Vì sao Parquet phù hợp lưu bảng trong lake hơn JSON gzip cho truy vấn chọn vài cột?','Định dạng cột hỗ trợ chỉ đọc cột cần và đẩy điều kiện lọc xuống file',['Mỗi truy vấn buộc giải nén mọi trường thành text','Parquet chỉ dùng truyền message Kafka','Parquet loại bỏ nhu cầu schema hoàn toàn'],'Bảng nêu Parquet theo cột và predicate pushdown; cảnh báo JSON gzip phải parse toàn lịch sử.')
mc(d,18,'Trong dbt, ref() đóng vai trò nào?','Tạo quan hệ phụ thuộc để xác định thứ tự chạy model',['Chỉ đổi tên bảng ngẫu nhiên','Tự cấp GPU cho transform','Thay mọi contract bằng ghi chú'],'ref() tự sinh đồ thị dependency nên dbt biết thứ tự chạy.')
mc(d,19,'Một model incremental bỏ is_incremental(). Hậu quả nào được nguồn nêu?','Mỗi lần chạy có thể quét lại toàn bộ lịch sử',['Mọi lần chạy tự động bỏ qua dữ liệu mới','Khóa unique_key tự biến mất','Bronze tự khôi phục dữ liệu đã hết TTL'],'Slide liệt kê thiếu is_incremental() làm mỗi lần chạy quét toàn bộ lịch sử.')
mc(d,20,'Đội đau vì backfill nhầm và môi trường dev quá đắt. Theo phần so sánh, lựa chọn nào đáng cân nhắc?','SQLMesh với phân tích thay đổi và virtual environment',['Thêm script SQL dùng chung không version','Bỏ test để giảm thời gian build','Dùng dbt chỉ vì nó không cần review'],'SQLMesh được gợi ý khi backfill sai và dev đắt; có phân loại breaking change và môi trường ảo bằng view.')
mc(d,21,'Bảng thực thể nhận các bản sửa CDC nên ưu tiên kỹ thuật idempotent nào?','MERGE/upsert theo khóa tin cậy',['Chỉ INSERT sau mọi retry','Xóa ngẫu nhiên một số hàng trùng','Đổi tên bảng mỗi lần chạy'],'Bảng idempotency ghép MERGE/upsert với bản ghi được sửa về sau và yêu cầu khóa tin cậy.')
mc(d,22,'Nhãn của ticket cũ được người dùng sửa. Cách quản lý training snapshot nào phù hợp nguồn?','Tạo version mới, giữ snapshot cũ bất biến',['Sửa âm thầm snapshot cũ để cùng tên luôn có nội dung mới','Xóa mọi version cũ trước khi train','Không ghi nhận nhãn đến muộn'],'Slide yêu cầu không sửa snapshot training cũ khi nhãn đổi, hãy tạo version mới.')
mc(d,23,'SCD Type 2 hỗ trợ câu hỏi nào mà bảng overwrite hiện trạng không trả lời được?','Trạng thái thực thể tại một thời điểm quá khứ',['GPU nào có throughput cao nhất','Mọi prompt nào là an toàn','Dung lượng RAM của consumer'],'SCD2 lưu valid_from, valid_to và is_current để join point-in-time thay vì chỉ giữ trạng thái hôm nay.')
mc(d,24,'Kiểm schema DataFrame ngay trong bước Python nên cân nhắc công cụ nào theo bảng?','Pandera',['Pydantic chỉ để chạy SQL warehouse','SCPs','Kafka broker'],'Bảng data testing gắn Pandera với schema DataFrame trong tiến trình Python; Pydantic ở mức từng payload/record.')
mc(d,26,'Cần truy vấn xuyên S3, Postgres và Kafka mà không di chuyển dữ liệu. Engine nào phù hợp mô tả?','Trino',['Ray Data chỉ vì có GPU','Airflow vì là SQL engine','Pydantic vì quản lý cluster'],'Trino được nêu là MPP truy vấn liên kho; Ray Data nhắm batch inference/embedding.')
mc(d,29,'Nhiều file 2MB làm thời gian planning lớn. Biện pháp nào đánh đúng vấn đề?','Compaction định kỳ và giảm số task ghi cuối pipeline',['Partition theo user_id để có nhiều file hơn','Chỉ tăng số consumer mà giữ nguyên mọi file nhỏ','Chuyển toàn bộ file thành JSON gzip'],'Small-file problem được xử lý bằng file lớn hơn, compaction và giảm task ghi; high-cardinality partition làm tệ hơn.')
mc(d,32,'Kafka retention 24 giờ nhưng backfill cần ba ngày. Kết luận nào phù hợp?','Không thể dựa vào topic đó để replay đủ ba ngày',['Offset của consumer tự phục hồi dữ liệu hết retention','Tăng số partition sẽ trả lại message đã hết hạn','Mỗi consumer luôn có lịch sử riêng vô hạn'],'Retention quyết định replay được bao xa; ví dụ 24h không đáp ứng lookback ba ngày.')
mc(d,39,'Workflow agent kéo dài nhiều ngày và cần durable execution/retry trong runtime nên cân nhắc gì theo bảng?','Temporal',['Trino như scheduler','Parquet như orchestrator','dbt tests thay state runtime'],'Temporal được mô tả với durable execution cho workflow nhiều ngày, agent nhiều bước; không phải scheduler data thông thường.')

