mc(d,7,'Điều gì khiến một hệ thống có thể được xem là agent theo phần mở đầu?','Quyết định, hành động, quan sát rồi lặp lại',['Chỉ nối LLM với bất kỳ API nào','Chỉ trả lời văn bản dài hơn chatbot','Chỉ thay if/else bằng prompt cố định'],'Slide nhấn mạnh agent xuất hiện khi có chu trình quyết định, hành động, quan sát và lặp.')
mc(d,8,'Rủi ro nào tăng thêm khi từ LLM chatbot sang agent theo bảng?','Tool misuse và loop ngoài hallucination',['Chỉ lỗi chính tả, không còn hallucination','Mất hoàn toàn khả năng gọi tool','Chi phí luôn thấp hơn rule-based bot'],'Bảng gắn agent với hallucination, tool misuse và loop cùng cost cao hơn do nhiều calls.')
mc(d,9,'Use case tìm vé mới rồi xét thời tiết cần agent ở điểm nào?','Truy vấn dữ liệu mới qua các tool và tổng hợp nhiều điều kiện',['Chỉ viết lại câu hỏi của người dùng','Luôn trả lời bằng menu cố định','Dự đoán giá vé từ trí nhớ model'],'Ví dụ reactive agent tách goal, gọi tool vé và thời tiết rồi so sánh/tổng hợp kết quả.')
mc(d,11,'Tiêu chí Dynamic Decision trong Agentic Fit hỏi về điều gì?','Bước tiếp theo phụ thuộc kết quả vừa quan sát hay không',['Model có bao nhiêu tham số','Context window chứa bao nhiêu trang','Giao diện có dùng màu động hay không'],'Dynamic Decision xét quan hệ giữa bước tiếp theo và observation mới.')
mc(d,14,'Customer FAQ chủ yếu retrieve policy và trả lời với intent ổn định. Kiến trúc được ví dụ chọn là gì?','Chatbot có retrieval',['Agent tự chủ luôn mở loop nhiều bước','Distributed training cluster','Rule cấm mọi retrieval'],'Case study cho Customer FAQ best fit chatbot có retrieval, chưa cần autonomy.')
mc(d,15,'Nhóm cần các bước nối tiếp đã rõ ràng, chưa cần tự quyết nhiều vòng. Pattern nào trong thang tăng dần phù hợp?','Prompt chaining',['Agent tự chủ là bắt buộc cho mọi chuỗi','Long-term memory thay toàn bộ luồng','Orchestrator-worker chỉ để lưu context'],'Slide mô tả Prompt Chaining là bước nối tiếp rõ ràng và khuyên dùng cấu trúc đơn giản đủ nhu cầu.')
mc(d,17,'Tool output đi vào agent trước hết thuộc chức năng nào của kiến trúc?','Perception',['Action như một API call mới','Long-term storage bắt buộc','Final answer bắt buộc'],'Perception nhận user input, tool output và feedback; reasoning chọn bước tiếp theo.')
mc(d,18,'Thêm long-term memory cần thiết kế bổ sung gì theo nguồn?','Chiến lược retrieval và mô hình quyền truy cập',['Chỉ tăng nhiệt độ sampling','Không cần quy tắc đọc/ghi vì memory luôn hữu ích','Chuyển mọi dữ liệu vào context không giới hạn'],'Long-term memory ngoài context có thể dùng DB/vector/key-value store nhưng cần retrieval strategy và permission model.')
mc(d,19,'Tool definition tốt phải làm rõ bộ thông tin nào?','Input, output và error mode',['Chỉ tên hấp dẫn của tool','Chỉ số lượng token tối đa của model','Chỉ biểu tượng của API'],'Nguồn yêu cầu tool definitions rõ input/output/error mode vì tool là external dependency có thể fail.')
mc(d,21,'Trong ReAct, Observation tương ứng với thành phần nào?','Kết quả do tool trả về',['Lời gọi tool và các tham số','Mục tiêu người dùng ban đầu duy nhất','Một suy đoán không cần evidence'],'Thought xác định thiếu gì; Action chọn tool/args; Observation là kết quả tool.')
mc(d,22,'Vì sao trace ReAct hỗ trợ debug tốt hơn chỉ xem final answer?','Cho thấy quyết định hành động và kết quả quan sát từng bước',['Bảo đảm mọi tool luôn thành công','Loại bỏ hoàn toàn nhu cầu evaluation','Giấu mọi action khỏi người vận hành'],'Slide nêu lý do hành động được bộc lộ qua trace nên con người debug/can thiệp dễ hơn.')
mc(d,25,'Khi ReAct workflow có nhiều nhánh và state phức tạp hơn, nguồn gợi ý chuyển sang gì?','Graph/state machine rõ ràng',['Tăng loop vô hạn cho đến khi tự ổn định','Chỉ nối các prompt trong một chuỗi text không state','Bỏ trace để giảm độ phức tạp'],'ReAct có giới hạn; graph/state machine rõ ràng phù hợp hệ nhiều nhánh hơn.')
mc(d,28,'Tool thất bại trong system prompt mẫu. Agent nên làm gì?','Giải thích lỗi và thử fallback',['Bịa tool result để hoàn tất câu trả lời','Gọi cùng tool vô hạn mà không thông báo','Chuyển lỗi thành một fact đã xác minh'],'System prompt mẫu cấm invent tool results và yêu cầu explain failure, try fallback.')
mc(d,30,'Observation không đổi nhưng agent tiếp tục gọi cùng tool. Can thiệp nào phù hợp?','Dừng loop và fallback theo safeguard',['Tăng max iterations vô hạn','Coi việc gọi lại là bằng chứng tiến triển','Xóa budget token để agent thử mãi'],'Slide coi tool lặp/không tiến triển/observation không đổi là dấu hiệu cần dừng và fallback.')
mc(d,31,'LangGraph làm rõ những thành phần nào của workflow so với loop ad-hoc?','State, nodes, edges và conditional routing',['Chỉ giá vé trong tool travel','Chỉ trọng số pre-training của model','Chỉ CSS của chatbot'],'Nguồn nêu graph approach biểu diễn rõ state/nodes/edges/conditional routing, dễ maintain khi nhiều nhánh hoặc persist state.')
